INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT144-S2-Q6$batch09$, 144, 2, 6, $batch09$Principle-Strengthen$batch09$, $batch09$Lawyer: In addition to any other penalties, convicted criminals must now pay a “victim surcharge” of $30. The surcharge is used to fund services for victims of violent crimes, but this penalty is unfair to nonviolent criminals since the surcharge applies to all crimes, even nonviolent ones like petty theft.$batch09$, $batch09$Which one of the following principles, if valid, would most help to justify the reasoning in the lawyer’s argument?$batch09$, $batch09$D$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=144 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$The penalties for a crime should be severe enough to deter most people who would commit the crime if there were no penalties.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$The overall penalty for a violent crime should be more severe than the overall penalty for any nonviolent crime.$batch09$, $batch09$Doesn't Reach$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$A surcharge intended to provide services to victims is justified only if all proceeds of the surcharge are used to provide services.$batch09$, $batch09$Not Shown$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$A criminal should not be required to pay for services provided to victims of crimes that are more serious than the type of crime the criminal has been convicted of.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Convicted thieves should be fined an amount at least as great as the value of the property stolen.$batch09$, $batch09$Out of Scope$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The victim surcharge is unfair to nonviolent criminals.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The surcharge funds services for victims of violent crimes, but it applies to every crime, including nonviolent ones like petty theft.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The lawyer's complaint is a mismatch. Someone convicted of petty theft pays for services for victims of violent crime, a more serious kind of crime than theirs. The principle has to say that's not a fair thing to make a criminal pay for.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Criminals shouldn't have to pay for services for victims of crimes more serious than their own.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Deterrence never comes up. The lawyer's objection is about who pays for what.$batch09$), ($batch09$B$batch09$, $batch09$This compares overall penalties. The surcharge is added "in addition to any other penalties", so violent criminals may still pay more overall. B doesn't make the surcharge unfair.$batch09$), ($batch09$C$batch09$, $batch09$Nothing suggests the money is spent on anything other than services. The lawyer's complaint is who pays, not where the money goes.$batch09$), ($batch09$D$batch09$, $batch09$A petty thief pays for services for victims of violent crime, which is more serious than petty theft. D says that criminal shouldn't have to pay, so the surcharge is unfair to nonviolent criminals.$batch09$), ($batch09$E$batch09$, $batch09$Fines for theft based on the value stolen have nothing to do with the victim surcharge.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT144-S2-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
